// Computes the total rendered width of a box, like the browser does
function totalWidth(box, boxSizing) {
  const { content, padding, border, margin } = box;
  if (boxSizing === "border-box") {
    return content + 2 * margin;
  }
  return content + 2 * (padding + border + margin);
}
console.log(totalWidth({ content: 200, padding: 20, border: 5, margin: 10 }, "content-box"));

